style:
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin-top: 10px;
}
.menu-item {
  background: #f5f7fa;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  padding: 12px;
  text-align: center;
  transition: all 0.2s ease;
}
.menu-item:hover {
  background: #e0ecff;
  border-color: #4a90e2;
}
.menu-item a {
  text-decoration: none;
  color: #333;
  font-weight: 600;
  display: block;
}
.menu-icon {
  font-size: 24px;
  margin-bottom: 6px;
  color: #4a90e2;
}

