.erp-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-family: Arial, sans-serif;
}
.erp-tile {
  width: 160px;
  height: 140px;
  background: #f4f6f8;
  border-radius: 8px;
  text-align: center;
  padding: 16px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  transition: 0.2s ease;
}
.erp-tile:hover {
  background: #e2e6ea;
  transform: translateY(-2px);
}
.hidden {
  display: none !important;
}

.erp-icon {
  font-size: 32px;
  margin-bottom: 12px;
  display: block;
}
.erp-label {
  font-weight: bold;
  color: #333;
  text-decoration: none;
}
